const e="Là où la forêt s'arrête, la montagne commence.",t="Proverbe Virelith",s=["Peuple & Lignée","Elfes des Montagnes","Codex #PEU-007"],n=[6,7,8],o="Montagnes de Trésabia, Reliefs du Vieux Monde",i="Endurance, Maîtrise de la roche, Discrétion",a="165cm - 185cm",l="300",r="« Peuple de la pierre obscure »",c="Virelith_icone.jpeg",u="Peu Commun",d=[{title:"Présentation",type:"text",content:"Les Virelith sont les Elfes des montagnes installés sur les falaises et sommets entourant Trésabia. Ils ont fondé une société axée sur l'endurance et la résistance."},{title:"Les Gardiens des Montagnes",type:"text",content:"Tandis que les Lythari protègent les forêts, les Virelith verrouillent les passages montagneux et les vallées encaissées."},{title:"Relations politiques",type:"politique_list_long",content:[{headline:"Alliance",title:"Les Lythari",content:"Coopération totale pour former un système défensif inexpugnable autour de Trésabia.",color:"#34D399"},{headline:"Tendu",title:"Les Kovraks",content:"Disputes frontalières fréquentes près des montagnes de Koven.",color:"#FF7A5C"}]},{title:"Aujourd'hui",type:"text",content:"Ils vivent reclus dans leurs cités troglodytes et leurs vallées fortifiées, formant l'un des peuples les plus discrets du Vieux Monde."}],p={citation:e,citation_author:t,tags:s,link_articles:n,class:"Elfique",repart:o,trait:i,height:a,age:l,surname:r,image:c,statut:u,sections:d};export{l as age,e as citation,t as citation_author,p as default,a as height,c as image,n as link_articles,o as repart,d as sections,u as statut,r as surname,s as tags,i as trait};
